# Local-derived (PP fixes C1, C2). Corroboration only; the c-2 proof is in the erratum (Witt + stabiliser-in-SO + reflection).
# (s11b: the s11 launch failed before the script was written; the empty s11 log is kept on record.)
# (1) Split (V,B) = F_q^{2n}, B = [[0,I],[I,0]], q odd: enumerate Lagrangians and compute the orbit of U0 under the group generated by
#     products r_v0 r_w of two reflections (a subgroup of SO).
# (2) c-3: vol(K_23) under Weil's canonical measure = #SO48(F23) * 23^-1128 (exact rational), and its inverse vs the carried 1.0019.
import itertools
from fractions import Fraction as F
def rref_span(vecs,q):
    M=[list(v) for v in vecs]; r=0; m=len(M[0]) if M else 0
    for c in range(m):
        p=next((i for i in range(r,len(M)) if M[i][c]%q),None)
        if p is None: continue
        M[r],M[p]=M[p],M[r]; iv=pow(M[r][c],q-2,q); M[r]=[x*iv%q for x in M[r]]
        for i in range(len(M)):
            if i!=r and M[i][c]%q: f=M[i][c]; M[i]=[(a-f*b)%q for a,b in zip(M[i],M[r])]
        r+=1
    return tuple(tuple(x) for x in M[:r])
def run(n,q):
    N=2*n
    def B(x,y): return sum(x[i]*y[n+i]+x[n+i]*y[i] for i in range(n))%q
    vecs=[v for v in itertools.product(range(q),repeat=N)]
    sing=[v for v in vecs if any(v) and B(v,v)==0]
    lag=set()
    def extend(basis,last):
        S=rref_span(basis,q) if basis else ()
        if len(S)==n: lag.add(S); return
        for i in range(last+1,len(sing)):
            v=sing[i]
            if all(B(v,b)==0 for b in basis) and len(rref_span(basis+[v],q))==len(S)+1: extend(basis+[v],i)
    extend([],-1)
    def refl(v):
        iv=pow(B(v,v),q-2,q)
        return lambda x: tuple((xi-2*B(x,v)*iv*vi)%q for xi,vi in zip(x,v))
    aniso=[v for v in vecs if B(v,v)%q]
    U0=rref_span([tuple(1 if j==i else 0 for j in range(N)) for i in range(n)],q)
    r0=refl(aniso[0])
    gens=[(lambda r2: (lambda x: r0(r2(x))))(refl(w)) for w in aniso]
    orbit={U0}; frontier=[U0]
    while frontier:
        nf=[]
        for U in frontier:
            for g in gens:
                W=rref_span([g(u) for u in U],q)
                if W not in orbit: orbit.add(W); nf.append(W)
        frontier=nf
    prod=1
    for i in range(1,n): prod*=q**i+1
    other=rref_span([r0(u) for u in U0],q)
    print(f'n={n} q={q}: #Lagrangians={len(lag)} (formula {2*prod}); orbit of U0 under <r_v0 r_w> = {len(orbit)} (claimed {prod}); r_v0 U0 in that orbit: {other in orbit}',flush=True)
for n,q in [(1,3),(2,3),(2,5),(3,3)]: run(n,q)
p=23; v=1-F(1,p**24)
for i in range(1,24): v*=1-F(1,p**(2*i))
order=p**552*(p**24-1)
for i in range(1,24): order*=p**(2*i)-1
assert F(order,p**1128)==v
print('c-3: #SO48(F23) = 23^552 (23^24-1) prod_{i=1}^{23}(23^{2i}-1); vol(K23) = #SO48(F23)/23^1128 exactly; 1/vol =',float(1/v))
